// FILE: src/features/producao/ui/PadronizarNomesProducaoButton.tsx
// TEMP: ferramenta temporária de padronização de nomes de Produção Diária — remover após uso (jun/2026).

import { useState, useEffect, useCallback, useMemo } from 'react';
import { Tags, Check, Loader2, Search, AlertCircle } from 'lucide-react';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Badge } from '@/shared/ui/badge';
import {
  Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle, DialogTrigger,
} from '@/shared/ui/dialog';
import {
  AlertDialog, AlertDialogAction, AlertDialogCancel, AlertDialogContent,
  AlertDialogDescription, AlertDialogFooter, AlertDialogHeader, AlertDialogTitle,
} from '@/shared/ui/alert-dialog';
import { toast } from '@/shared/hooks/use-toast';
import { supabase } from '@/integrations/supabase/client';
import { useQueryClient } from '@tanstack/react-query';

interface DailyProductionItem {
  product_name: string;
}

interface ProductCount {
  name: string;
  count: number;
}

interface FuseCandidate {
  nameA: string;
  nameB: string;
  countA: number;
  countB: number;
}

export function PadronizarNomesProducaoButton() {
  const [open, setOpen] = useState<boolean>(false);
  const [items, setItems] = useState<ProductCount[]>([]);
  const [loading, setLoading] = useState<boolean>(false);
  const [fetchError, setFetchError] = useState<string | null>(null);
  const [editMap, setEditMap] = useState<Map<string, string>>(new Map());
  const [savingSet, setSavingSet] = useState<Set<string>>(new Set());
  const [search, setSearch] = useState<string>('');
  const [fuseCandidate, setFuseCandidate] = useState<FuseCandidate | null>(null);

  const queryClient = useQueryClient();

  const normalizeAndLowercase = useCallback((text: string): string => {
    return text.normalize('NFC').toLowerCase();
  }, []);

  const fetchProductNames = useCallback(async () => {
    setLoading(true);
    setFetchError(null);
    const productNamesMap = new Map<string, number>();
    let from = 0;
    const PAGE = 1000;
    let hasMore = true;

    try {
      while (hasMore) {
        const { data, error } = await supabase
          .from('daily_production')
          .select('product_name')
          .range(from, from + PAGE - 1)
          .returns<DailyProductionItem[]>();

        if (error) throw error;

        if (data) {
          data.forEach((item) => {
            if (item.product_name) {
              productNamesMap.set(
                item.product_name,
                (productNamesMap.get(item.product_name) ?? 0) + 1,
              );
            }
          });
        }

        from += PAGE;
        hasMore = data !== null && data.length === PAGE;
      }

      const aggregatedItems: ProductCount[] = Array.from(productNamesMap.entries()).map(
        ([name, count]) => ({ name, count }),
      );

      aggregatedItems.sort((a, b) => a.name.localeCompare(b.name, 'pt-BR'));
      setItems(aggregatedItems);
    } catch (err: unknown) {
      setFetchError((err as Error).message || 'Erro ao carregar nomes de produtos.');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (open) {
      void fetchProductNames();
    } else {
      setItems([]);
      setEditMap(new Map());
      setSavingSet(new Set());
      setSearch('');
      setFuseCandidate(null);
      setFetchError(null);
    }
  }, [open, fetchProductNames]);

  const filteredItems = useMemo(() => {
    if (!search) return items;
    const normalizedSearch = normalizeAndLowercase(search);
    return items.filter((item) =>
      normalizeAndLowercase(item.name).includes(normalizedSearch),
    );
  }, [items, search, normalizeAndLowercase]);

  const handleEditChange = useCallback((oldName: string, newValue: string) => {
    setEditMap((prev) => {
      const next = new Map(prev);
      next.set(oldName, newValue);
      return next;
    });
  }, []);

  const handleSave = useCallback(
    async (oldName: string, newNameInput: string, isMergeConfirmed = false) => {
      const trimmedNewName = newNameInput.trim();

      if (trimmedNewName === '' || trimmedNewName === oldName) {
        setEditMap((prev) => {
          const next = new Map(prev);
          next.delete(oldName);
          return next;
        });
        return;
      }

      if (!isMergeConfirmed) {
        const existingItem = items.find(
          (item) =>
            item.name !== oldName &&
            normalizeAndLowercase(item.name) === normalizeAndLowercase(trimmedNewName),
        );

        if (existingItem) {
          const oldItem = items.find((item) => item.name === oldName);
          if (oldItem) {
            setFuseCandidate({
              nameA: oldName,
              nameB: existingItem.name,
              countA: oldItem.count,
              countB: existingItem.count,
            });
            return;
          }
        }
      }

      setSavingSet((prev) => new Set(prev).add(oldName));

      try {
        // TEMP: RPC SECURITY DEFINER renomeia TODAS as linhas do nome (bypass controlado
        // da RLS por autor — 64% dos lançamentos são cross-autor). Retorna a contagem real.
        // @ts-expect-error função TEMP ainda não consta no types.ts gerado do Supabase
        const { data: affected, error } = await supabase.rpc('padronizar_nome_producao_diaria', {
          p_old_name: oldName,
          p_new_name: trimmedNewName,
        });

        if (error) throw error;

        const count = typeof affected === 'number' ? affected : 0;

        toast({
          title: isMergeConfirmed ? 'Itens fundidos' : 'Nome atualizado',
          description: isMergeConfirmed
            ? `${count} lançamento(s) de "${oldName}" fundido(s) em "${trimmedNewName}"`
            : `${count} lançamento(s) renomeado(s) para "${trimmedNewName}"`,
        });

        await fetchProductNames();
        queryClient.invalidateQueries({ queryKey: ['daily_production'] });
        queryClient.invalidateQueries({ queryKey: ['producao'] });

        setEditMap((prev) => {
          const next = new Map(prev);
          next.delete(oldName);
          return next;
        });
      } catch (err: unknown) {
        toast({
          title: 'Erro ao renomear',
          description: (err as Error).message || 'Tente novamente.',
          variant: 'destructive',
        });
      } finally {
        setSavingSet((prev) => {
          const next = new Set(prev);
          next.delete(oldName);
          return next;
        });
        setFuseCandidate(null);
      }
    },
    [fetchProductNames, items, normalizeAndLowercase, queryClient],
  );

  const handleConfirmMerge = useCallback(() => {
    if (fuseCandidate) {
      void handleSave(fuseCandidate.nameA, fuseCandidate.nameB, true);
    }
  }, [fuseCandidate, handleSave]);

  const handleCancelMerge = useCallback(() => {
    if (fuseCandidate) {
      setEditMap((prev) => {
        const next = new Map(prev);
        next.delete(fuseCandidate.nameA);
        return next;
      });
    }
    setFuseCandidate(null);
  }, [fuseCandidate]);

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button
          variant="outline"
          className="h-10 rounded-full border-[#57715B]/20 bg-[#E6DCCF]/40 px-3 text-[#57715B] hover:bg-[#57715B]/10 dark:border-white/10 dark:bg-white/10 dark:text-[#8FA893] transition-all hover:scale-105"
