    });

    // Aguardar que rpc seja chamado
    await waitFor(() => {
      expect(rpcFn).toHaveBeenCalledTimes(1);
    });

    // CRÍTICO: rpc deve ser chamado com o nome correto da função e args SOMENTE p_old_name + p_new_name
    const [rpcName, rpcArgs] = rpcFn.mock.calls[0] as [string, Record<string, unknown>];
    expect(rpcName).toBe('padronizar_nome_producao_diaria');
    expect(rpcArgs).toEqual({ p_old_name: 'Brownie', p_new_name: 'Brownie Vegano' });
    // Garante que não há chaves extras além das esperadas
    expect(Object.keys(rpcArgs)).toEqual(['p_old_name', 'p_new_name']);
  });

  // ── Caso 4: Aviso de fusão (AlertDialog) ───────────────────────────────────
  it('4. renomear para nome já existente exibe AlertDialog de fusão; rpc NÃO é chamado antes de confirmar', async () => {
    let selectCallCount = 0;

    (supabase.from as ReturnType<typeof vi.fn>).mockImplementation(() => {
      selectCallCount++;
      const data = selectCallCount === 1 ? MOCK_PAGE_1 : [];
      return makeSelectChain({ data, error: null });
    });

    const rpcFn = supabase.rpc as ReturnType<typeof vi.fn>;

    renderWithProviders(<PadronizarNomesProducaoButton />);

    // Abrir dialog
    await act(async () => {
      fireEvent.click(screen.getByRole('button', { name: /padronizar nomes/i }));
    });

    await waitFor(() => {
      expect(screen.getByDisplayValue('Brownie')).toBeInTheDocument();
    });

    // Renomear "Brownie" para "brigadeiro" (nome que já existe na lista)
    const input = screen.getByDisplayValue('Brownie');
    await act(async () => {
      await userEvent.clear(input);
      await userEvent.type(input, 'brigadeiro');
    });

    await act(async () => {
      fireEvent.keyDown(input, { key: 'Enter', code: 'Enter' });
    });

    // AlertDialog de confirmação de fusão deve aparecer
    await waitFor(() => {
      expect(screen.getByText(/confirmar fus[aã]o de itens/i)).toBeInTheDocument();
    });

    // rpc NÃO deve ter sido chamado antes de confirmar "Fundir"
    expect(rpcFn).not.toHaveBeenCalled();

    // Verificar que o botão "Fundir" está presente
    expect(screen.getByRole('button', { name: /fundir/i })).toBeInTheDocument();
  });
